    pub fn ty<'db>(&self, db: &'db dyn HirDatabase) -> TypeNs<'db> {
        let var_id = self.parent.into();
        let ty = db.field_types(var_id)[self.id].get().skip_binder();
        TypeNs::new(db, var_id, ty)
